// bridge_path.ts — honors BAML_BRIDGE_PATH before the napi-generated loader runs.
//
// `index.ts` imports this module first, so it evaluates before `./native.js`
// (generated by `napi build`, never edited by hand). When BAML_BRIDGE_PATH is
// set it must be an absolute path to a loadable .node file; anything else is a
// hard error with no fallback to the packaged binary. The file is loaded here
// and handed to the generated loader through its own NAPI_RS_NATIVE_LIBRARY_PATH
// convention, so the loader resolves it from the module cache and never probes
// platform packages. When unset, the generated loader runs unchanged.
import { createRequire } from 'node:module';
import { existsSync } from 'node:fs';
import { isAbsolute } from 'node:path';

const VARIABLE = 'BAML_BRIDGE_PATH';

export function applyBridgePathOverride(env: NodeJS.ProcessEnv = process.env): void {
    const configured = env[VARIABLE];
    if (configured === undefined || configured === '') {
        return;
    }
    if (!isAbsolute(configured)) {
        throw new Error(`${VARIABLE} must be an absolute native-library file path; received ${configured}.`);
    }
    if (!existsSync(configured)) {
        throw new Error(`${VARIABLE} file does not exist: ${configured}.`);
    }
    try {
        createRequire(import.meta.url)(configured);
    } catch (cause) {
        throw new Error(
            `Failed to load the exact ${VARIABLE} file ${configured}; packaged fallback is disabled.`,
            { cause },
        );
    }
    env.NAPI_RS_NATIVE_LIBRARY_PATH = configured;
}

applyBridgePathOverride();
